UPDATE sys_plan
plan_number = #{planNumber}, plan_name = #{planName}, plan_version = #{planVersion}, plan_start_time = #{planStartTime}, plan_end_time = #{planEndTime}, create_by_id = #{createById}, create_time = #{createTime}, update_by_id = #{updateById}, update_time = #{updateTime}, project_id = #{projectId}, remark = #{remark},
WHERE plan_id = #{planId}

UPDATE sys_plan
update_by_id = #{updateById}, update_time = #{updateTime},
WHERE plan_id = #{planId}

