            OR (m.module_name IS NOT NULL AND m.module_name LIKE CONCAT('%', #{defect.nameVersionKeyword}, '%'))

                OR (

                    d.handle_by REGEXP CONCAT('\b', #{b}, '\b') OR d.handle_by REGEXP CONCAT('\\b', #{b}, '\\b')

                )

        )


        AND (
            d.defect_name LIKE CONCAT('%', #{defect.params.nameVersionKeyword}, '%')
            OR d.defect_name = #{defect.params.nameVersionKeyword}
            OR CONCAT(d.project_num, '') LIKE CONCAT('%', #{defect.params.nameVersionKeyword}, '%')
            OR (d.module_version IS NOT NULL AND d.module_version LIKE CONCAT('%', #{defect.params.nameVersionKeyword}, '%'))
            OR (m.module_name IS NOT NULL AND m.module_name LIKE CONCAT('%', #{defect.params.nameVersionKeyword}, '%'))

                OR (

                    d.handle_by REGEXP CONCAT('\b', #{b}, '\b') OR d.handle_by REGEXP CONCAT('\\b', #{b}, '\\b')

                )

        )



            AND (d.defect_name LIKE CONCAT('%', #{defect.defectName}, '%') OR d.defect_name = #{defect.defectName})


            AND d.module_version LIKE CONCAT('%', #{defect.moduleVersion}, '%')



AND d.project_id = #{defect.projectId}
AND d.test_plan_id = #{defect.testPlanId}
AND d.case_id = #{defect.caseId}
