SELECT DISTINCT d.defect_id, d.project_num, d.defect_type, d.defect_name, d.defect_describe, d.defect_level, d.defect_state, d.module_id, m.module_name, d.module_version, d.project_id, d.case_id, d.test_plan_id, d.case_step_id, d.create_by, d.create_by_id, d.create_time, d.update_by, d.update_by_id, d.update_time, d.handle_by, d.handle_time, d.img_urls, d.annex_urls, d.plan_start_time, d.plan_end_time, d.del_flag
ORDER BY ${_pageOrder} ORDER BY d.defect_id DESC
LIMIT #{limit} OFFSET #{offset}
